package com.rikkeibank.transaction.service;import com.rikkeibank.common.api.BusinessException;import com.rikkeibank.transaction.domain.BankTransaction;import com.rikkeibank.transaction.repo.TransactionRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class TransactionQueryService{private final TransactionRepository repo;public TransactionQueryService(TransactionRepository r){repo=r;}public BankTransaction get(UUID id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Transaction not found"));}public List<BankTransaction>mine(UUID id){return repo.findByCustomerIdOrderByCreatedAtDesc(id);}public List<BankTransaction>today(UUID teller,ZoneId zone){LocalDate d=LocalDate.now(zone);return repo.findByAssignedTellerIdAndCreatedAtBetweenOrderByCreatedAtDesc(teller,d.atStartOfDay(zone).toInstant(),d.plusDays(1).atStartOfDay(zone).toInstant());}@Transactional public BankTransaction assign(UUID id,UUID teller){BankTransaction t=get(id);t.assign(teller);return t;}}

